var extracted = $('Parse Extraction').item.json.extracted_terms;
var compliance = $('Parse Compliance').item.json.compliance_result;
var risk = $('Parse Risk').item.json.risk_result;
var quality = $('Parse Quality').item.json.quality;
var researchNotes = '';
try {
  var researched = $('Parse Re-Research').item.json;
  if (researched.extracted_terms) extracted = researched.extracted_terms;
  if (researched.compliance_result) compliance = researched.compliance_result;
  if (researched.risk_result) risk = researched.risk_result;
  if (researched.research_notes) researchNotes = researched.research_notes;
} catch(e) {}
try {
  var retryQuality = $('Parse Retry Quality').item.json.quality;
  if (retryQuality) quality = retryQuality;
} catch(e) {}

var riskScore = parseInt(risk.risk_score) || 10;
var riskLevel = riskScore <= 3 ? 'LOW' : riskScore <= 6 ? 'MEDIUM' : 'HIGH';
var decision = 'ESCALATE';
if (riskLevel === 'LOW' && compliance.overall_status === 'PASS') decision = 'APPROVE';
else if (riskLevel === 'HIGH') decision = 'REJECT';

var d = '=';
var div = '\n' + d.repeat(50) + '\n';
var out = d.repeat(50) + '\n  DEAL REVIEW REPORT\n  ID: DR-' + Date.now() + '\n  Date: ' + new Date().toLocaleDateString('en-US', {month:'long',day:'numeric',year:'numeric'}) + '\n' + d.repeat(50);
out += div + 'DECISION: ' + decision + '\nRisk: ' + riskScore + '/10 (' + riskLevel + ')\nCompliance: ' + (compliance.overall_status || '?') + ' (' + (compliance.rules_passed||'?') + '/' + (compliance.rules_checked||'?') + ' passed)\nQuality: ' + (quality.verdict||'?') + ' (' + (quality.completeness||'?') + '/10)';
if (researchNotes) out += '\nRe-research: ' + researchNotes;
out += div + 'DEAL SUMMARY\nType: ' + (extracted.deal_type||'?') + '\nPrincipal: ' + ((extracted.financial_terms&&extracted.financial_terms.principal_amount)||'N/A') + '\nRate: ' + ((extracted.financial_terms&&extracted.financial_terms.interest_rate)||'N/A') + '\nMaturity: ' + ((extracted.financial_terms&&extracted.financial_terms.maturity_date)||'N/A') + '\nLTV: ' + ((extracted.financial_terms&&extracted.financial_terms.ltv_ratio)||'N/A');
if (compliance.details && compliance.details.length > 0) { out += div + 'COMPLIANCE'; for (var i=0;i<compliance.details.length;i++) { var r=compliance.details[i]; out += '\n  [' + r.status + '] ' + (r.rule_name||'Rule '+r.rule_id) + ': ' + (r.finding||''); } }
if (compliance.critical_violations && compliance.critical_violations.length > 0) { out += div + 'CRITICAL'; for (var cv=0;cv<compliance.critical_violations.length;cv++) out += '\n  !! ' + compliance.critical_violations[cv]; }
if (compliance.warnings && compliance.warnings.length > 0) { out += div + 'WARNINGS'; for (var w=0;w<compliance.warnings.length;w++) out += '\n  >> ' + compliance.warnings[w]; }
if (risk.dimensions && risk.dimensions.length > 0) { out += div + 'RISK DIMENSIONS'; for (var rd=0;rd<risk.dimensions.length;rd++) { var dm=risk.dimensions[rd]; out += '\n  ' + dm.name + ': ' + dm.score + '/10 - ' + dm.assessment; } }
if (risk.red_flags && risk.red_flags.length > 0) { out += div + 'RED FLAGS'; for (var rf=0;rf<risk.red_flags.length;rf++) out += '\n  ** ' + risk.red_flags[rf]; }
if (risk.mitigating_factors && risk.mitigating_factors.length > 0) { out += div + 'MITIGATING'; for (var mf=0;mf<risk.mitigating_factors.length;mf++) out += '\n  ++ ' + risk.mitigating_factors[mf]; }
if (risk.summary) out += div + 'RISK SUMMARY\n' + risk.summary;
if (risk.historical_comparison) out += div + 'HISTORICAL\n' + risk.historical_comparison;
if (quality.gaps && quality.gaps.length > 0) { out += div + 'QUALITY GAPS'; for (var qg=0;qg<quality.gaps.length;qg++) out += '\n  -- ' + quality.gaps[qg]; }
out += div + 'RECOMMENDATION: ' + (risk.recommendation || decision) + '\n' + d.repeat(50);

return [{ json: { output: out, decision: decision, risk_score: riskScore, risk_level: riskLevel, deal_type: extracted.deal_type || 'Unknown', summary: risk.summary || '' } }];

